def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    result = v1 / v2

    return {
        "value": result,
        "trace": {
            "numerator": v1,
            "denominator": v2,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "proportion"
            }
        }
    }
